function _unwrapGithubCheckRuns(raw) {
    var parsed = _parseJson(raw);
    if (parsed && typeof parsed.result !== 'undefined') {
        parsed = _parseJson(parsed.result);
    }
    if (Array.isArray(parsed)) return parsed;
