            try {
                tracker.addLabel(ticketKey, 'agent:rework');
                console.log('✅ No-op rework: verdict head unchanged — agent:rework re-armed on ' + ticketKey);
            } catch (e) {
                console.warn('Failed to re-arm agent:rework on ' + ticketKey + ':', e.message || e);
