    } catch (e) {
        console.warn('Failed to move ticket back to ' + statuses.IN_REWORK + ':', e.message || e);
    }
    removeConfiguredLabels(tracker, ticketKey, customParams || {});
    return {
        success: false,
        path: 'rework-cli-failed',
        ticketKey: ticketKey,
        branchName: branchName
    };
}

