    try {
        fetchParentContextToInput.action(params);
    } catch (e) {
        console.warn('fetchParentContextToInput failed (non-fatal):', e);
    }

    return {
        success: true,
        prNumber: prDetails.number,
        prUrl: prDetails.html_url,
        branchName: branchName,
        owner: repoInfo.owner,
        repo: repoInfo.repo
    };

} catch (error) {
