        assert.contains(String(result.error), 'PR-LOOKUP-FAILED', 'greppable marker in the job result');
        assert.contains(String(result.error), 'pr-1212');
        assert.equal(fx.addCommentCalls.length, 0, 'nothing was posted to any PR');
