        if (!gateResult.success) {
            throw new Error('Quality gate failed before rework push: ' + gateResult.failedGate + '\n' + gateResult.error);
        }
        var policyResult = feedbackLoop.runPolicyGates({
            ticketKey: ticketKey,
            customParams: _customParams,
