                    errorTracker.postComment(
                        actualParams.ticket.key,
                        em.h(3, '❌ Rework Workflow Error') + '\n\n' + em.code(error.toString())
                    );
                }
            }
        } catch (e) {}
        return { success: false, error: error.toString() };
    }
}

