                    ticketKey,
                    qm.h(3, '❌ Rework Quality Gate Failed') + '\n\n' + qm.code(gateError) + '\n\nThe branch was pushed before running this gate. Please check the logs and retry.'
                );
            } catch (e) {}
            return { success: false, error: gateError };
