    // regression below passed only BECAUSE of the old silent skip; the lookup
    // failure path now fails loudly by design and needs its own test.
    var scm = Object.assign({
        listPrs: function() {
            return [{
                number: 123,
                title: 'PROJ-123: rework fix',
                head: { ref: 'bug/PROJ-123' },
