       // fixture modeled on the 'action() wires the contract' test
       ... config: { git: { baseBranch: 'master' }, workingDir: null, repository: {...}, jira: { markReworkInDevelopment: true }
       trackers: createTracker → { postComment, moveToStatus: function(k, s) { moves.push(s); }
       './config.js': { resolveStatuses: function() { return { IN_DEVELOPMENT: 'In Development', IN_REWORK: 'In Rework' }; }
       action({ inputFolderPath: 'input/PROJ-123', jobParams: { inputFolderPath: 'input/PROJ-123', customParams: {} })
       assert.deepEqual(moves, ['In Rework']);
   });
   ```

   Note: statuses stub needs IN_REWORK since the fix uses statuses.IN_REWORK. (The current stub only has IN_DEVELOPMENT — with the fix, statuses.IN_REWORK would be undefined → moveToStatus(key, undefined) → RED test fails with moves = [undefined]... which asserts the behavior change. Good RED.)

4. **test_fetchQuestionsToInput.js** (AC3c): extend the failing-search test (or add new): capture console.error, assert the logged content contains 'jira down':
   ```js
   test('a failing search logs the error CONTENT, not a swallowed {} (gh-802 AC3c)', function() {
       var errors = [];
       var origError = console.error;
       console.error = function() { errors.push(Array.prototype.slice.call(arguments).join(' ')); };
       try {
